import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const g=JSON.parse('{"title":"Catalogues & Reference","description":"Generated catalogues of everything AzureScout collects and assesses, plus category and validation reference.","frontmatter":{"description":"Generated catalogues of everything AzureScout collects and assesses, plus category and validation reference."},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),s={name:"reference/index.md"};function n(d,e,i,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="catalogues-reference" tabindex="-1">Catalogues &amp; Reference <a class="header-anchor" href="#catalogues-reference" aria-label="Permalink to &quot;Catalogues &amp; Reference&quot;">​</a></h1><p>The two questions everyone asks first — <em>what does it collect</em> and <em>what does it assess</em> — each have one page, and both are <strong>generated from the product</strong> rather than hand-maintained.</p><h2 id="the-two-catalogues" tabindex="-1">The two catalogues <a class="header-anchor" href="#the-two-catalogues" aria-label="Permalink to &quot;The two catalogues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./assessment-catalogue.html">Assessment Catalogue</a></td><td>All <strong>46 assessments</strong>, grouped into CAF design areas, WAF pillars, per-service slices and specialised reviews — with the rule files, rule counts, and the automated-versus-manual split behind each</td></tr><tr><td><a href="./framework-coverage.html">Framework Coverage</a></td><td><strong>How much of each framework actually has a rule behind it.</strong> Scout enumerates every framework in full; this is the gap between enumerating an item and testing it</td></tr><tr><td><a href="./arm-modules.html">ARM Modules</a></td><td>All <strong>242 collector definitions</strong> across Microsoft&#39;s 18 published service categories, each mapped to the resource types it targets</td></tr><tr><td><a href="./collector-fields.html">Collector Fields</a></td><td>The worksheet and the ordered columns each collector produces — what actually comes back, as opposed to what is covered</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Both pages are generated</p><p><code>scripts/Build-AssessmentCatalog.ps1</code> and <code>scripts/Build-ArmModuleCatalog.ps1</code> regenerate them from <code>manifests/</code>, and CI fails if a committed page and a fresh regeneration disagree. An earlier hand-maintained catalogue claimed to be generated and drifted fifteen collectors out of date before anyone noticed, which is why they are built this way now.</p></div><h2 id="supporting-reference" tabindex="-1">Supporting reference <a class="header-anchor" href="#supporting-reference" aria-label="Permalink to &quot;Supporting reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./entra-modules.html">Entra ID Modules</a></td><td>Identity collectors that query Microsoft Graph rather than ARM</td></tr><tr><td><a href="./coverage-table.html">Coverage Table</a></td><td>Service coverage per category, from the same pass over the manifests</td></tr><tr><td><a href="./category-structure.html">Category Structure</a></td><td>How the 18 categories are organised</td></tr><tr><td><a href="./category-reference.html">Category Reference</a></td><td>Every report section heading mapped to its category, aliases, and collector folder</td></tr><tr><td><a href="./validation-matrix.html">Validation Matrix</a></td><td>Which checks are verified by automated tests and which need a live tenant</td></tr><tr><td><a href="./react-report-section-contract.html">React Report Section Contract</a></td><td>The v6 page structure of the one supported deliverable, the register completeness rule, and what a section must satisfy so an assessment can be added without touching the shell</td></tr></tbody></table><h2 id="reading-a-count-on-any-page-here" tabindex="-1">Reading a count on any page here <a class="header-anchor" href="#reading-a-count-on-any-page-here" aria-label="Permalink to &quot;Reading a count on any page here&quot;">​</a></h2><p>Counts on these pages come from the manifests at generation time, so they match the shipped product exactly. Counts written into prose elsewhere in the documentation are maintained by hand and are the ones to distrust — if two pages disagree, these two win.</p>',9)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
